let state={},currentProject='default',currentSession=null,busy=false,mcpLogTimer=null,selections={prompts:[],skills:[],mcp:[]};const collapsedProjects=new Set();let usageSession=loadUsageSession();function loadUsageSession(){try{return JSON.parse(localStorage.getItem('agentUsageSession')||'{"input_tokens":0,"output_tokens":0,"total_tokens":0,"complete":true}') }catch{return {input_tokens:0,output_tokens:0,total_tokens:0,complete:true}}}function saveUsageSession(){localStorage.setItem('agentUsageSession',JSON.stringify(usageSession));renderUsagePanel()}function resetUsageSession(){usageSession={input_tokens:0,output_tokens:0,total_tokens:0,complete:true};saveUsageSession()}function addUsage(u){if(!u)return;for(const k of ['input_tokens','output_tokens']){if(Number.isInteger(u[k]))usageSession[k]+=u[k];else usageSession.complete=false}usageSession.total_tokens=usageSession.complete?usageSession.input_tokens+usageSession.output_tokens:null;saveUsageSession()}function renderUsagePanel(){const el=$('#usagePanel');if(!el)return;el.innerHTML=`<div class="usage-head"><span>TOKEN CONSUMPTION</span><button type="button" id="resetUsageBtn" title="Reset token counters">Reset</button></div><div class="usage-total">${usageSession.complete?usageSession.total_tokens.toLocaleString():'Partial'}</div><div class="usage-caption">Total tokens consumed</div><div class="usage-split"><span>Input <b>${usageSession.input_tokens.toLocaleString()}</b></span><span>Output <b>${usageSession.output_tokens.toLocaleString()}</b></span></div>`;$('#resetUsageBtn').onclick=resetUsageSession}
