async function refreshModelStatus(){try{const r=await api('/api/model/status');if(r.provider!==state.settings?.provider)return;const previousRunning=state.model_running;state.model_running=!!r.model_running;if(previousRunning!==undefined&&previousRunning!==state.model_running)resetUsageSession();state.models=Array.isArray(r.models)?r.models:[];state.model_owned=r.model_owned;const c=state.settings||{},pill=$('#modelStatus'),btn=$('#startModelBtn'),meta=$('#modelMeta'),picker=$('#activeModelSelect');if(pill){pill.classList.toggle('on',r.model_running||c.provider!=='ollama');pill.innerHTML=`<i></i> ${c.provider!=='ollama'?'External':r.model_running?'Online':'Offline'}`}if(btn){btn.style.display=c.provider==='ollama'?'':'none';btn.textContent=r.model_running?'Stop':'Start';btn.classList.toggle('stop',!!r.model_running);btn.disabled=false;btn.title=r.model_running?'Stop Ollama service':'Start Ollama service'}if(meta)meta.textContent=c.provider==='ollama'?(r.model_running?`${(state.models||[]).length} model(s) available`:'Waiting for Ollama connection'):`${c.base_url||'API endpoint configured'}`;if(picker&&document.activeElement!==picker){picker.innerHTML=modelOptions(c.model||'llama3.2');picker.value=c.model||'llama3.2'}updateChatAvailability()}catch(e){console.warn('Ollama status refresh failed:',e.message)}}
function modelOptions(selected){const models=[...new Set([...(state.models||[]),selected].filter(Boolean))];return models.map(m=>`<option value="${esc(m)}" ${m===selected?'selected':''}>${esc(m)}</option>`).join('')||'<option value="">No models found</option>'}
async function selectActiveModel(value){if(!value)return;try{if(value!==state.settings?.model)resetUsageSession();await api('/api/settings','PUT',{model:value});state.settings.model=value;renderRight();toast(`Active model: ${value}`)}catch(e){toast('Could not change model: '+e.message);await refreshModelStatus()}}
