function renderProjects(){const root=$('#projectList');root.innerHTML='';for(const p of state.projects){const box=document.createElement('div');box.className='project';const collapsed=collapsedProjects.has(p.id);const head=document.createElement('div');head.className='project-head';head.innerHTML=`<button class="project-collapse" title="${collapsed?'Expand':'Collapse'} project" aria-expanded="${!collapsed}">${collapsed?'▸':'▾'}</button><span class="project-name" title="${esc(p.name)}">${esc(p.name)}</span><span class="project-actions"><button class="project-add-chat" title="New conversation in ${esc(p.name)}" aria-label="New conversation in ${esc(p.name)}"><svg viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M10 4v12M4 10h12"/></svg></button><button class="project-rename" title="Rename project">✎</button>${p.id==='default'?'':'<button class="project-delete" title="Delete project">⌫</button>'}</span>`;const toggle=()=>{if(collapsedProjects.has(p.id))collapsedProjects.delete(p.id);else collapsedProjects.add(p.id);renderProjects()};head.querySelector('.project-collapse').onclick=toggle;head.querySelector('.project-name').onclick=toggle;head.querySelector('.project-add-chat').onclick=()=>{currentProject=p.id;createSession()};head.querySelector('.project-rename').onclick=()=>renameProject(p);const del=head.querySelector('.project-delete');if(del)del.onclick=()=>deleteProject(p);box.append(head);const sessions=document.createElement('div');sessions.className='project-sessions';sessions.hidden=collapsed;for(const s of state.sessions.filter(x=>x.project_id===p.id)){const row=document.createElement('div');row.className='session-row'+(s.id===currentSession?' active':'');row.innerHTML=`<span>◷</span><span class="session-name">${esc(s.title)}</span><button title="Rename">✎</button><button title="Delete">×</button>`;row.onclick=()=>openSession(s.id);row.querySelectorAll('button')[0].onclick=e=>{e.stopPropagation();renameSession(s)};row.querySelectorAll('button')[1].onclick=e=>{e.stopPropagation();deleteSession(s)};sessions.append(row)}box.append(sessions);root.append(box)}}
function renderRight(){const c=state.settings||{};const activeSelect=$('#activeModelSelect');if(activeSelect){activeSelect.innerHTML=modelOptions(c.model||'llama3.2');activeSelect.value=c.model||'llama3.2';activeSelect.onchange=()=>selectActiveModel(activeSelect.value)}$('#modelProvider').textContent=c.provider==='ollama'?'Local · Ollama':'External · OpenAI-compatible';const st=$('#modelStatus');st.classList.toggle('on',state.model_running||c.provider!=='ollama');st.innerHTML=`<i></i> ${c.provider!=='ollama'?'External':state.model_running?'Online':'Offline'}`;const modelBtn=$('#startModelBtn');modelBtn.style.display=c.provider==='ollama'?'':'none';modelBtn.textContent=state.model_running?'Stop':'Start';modelBtn.classList.toggle('stop',!!state.model_running);modelBtn.disabled=false;$('#modelMeta').textContent=c.provider==='ollama'?(state.model_running?`${(state.models||[]).length} model(s) available`:'Waiting for Ollama connection'):`${c.base_url||'API endpoint configured'}`;const reasoningToggle=$('#reasoningEnabled');if(reasoningToggle){reasoningToggle.checked=['1','true','yes','on'].includes(String(c.reasoning_enabled||'false').toLowerCase());reasoningToggle.onchange=async()=>{try{await api('/api/settings','PUT',{reasoning_enabled:reasoningToggle.checked});state.settings.reasoning_enabled=String(reasoningToggle.checked)}catch(e){toast(e.message);reasoningToggle.checked=!reasoningToggle.checked}}}const historyLimit=$('#historyLimit');if(historyLimit){historyLimit.value=String(c.history_limit||'all');historyLimit.onchange=async()=>{const value=historyLimit.value;try{await api('/api/settings','PUT',{history_limit:value});state.settings.history_limit=value;toast(value==='all'?'Sharing all conversation history':value==='0'?'Sharing no previous conversation messages':`Sharing the last ${value} messages`)}catch(e){toast(e.message);historyLimit.value=String(state.settings.history_limit||'all')}}}updateAgentInstructionsPreview();const sliders=[['temperatureRange','temperature','tempValue','0.7'],['topPRange','top_p','topPValue','0.9'],['repeatPenaltyRange','repeat_penalty','repeatPenaltyValue','1.1']];for(const [id,key,valueId,def] of sliders){const el=$('#'+id),v=String(c[key]||def);if(el){el.value=v;$('#'+valueId).textContent=v;el.oninput=()=>{$('#'+valueId).textContent=el.value};el.onchange=async()=>{await api('/api/settings','PUT',{[key]:el.value});state.settings[key]=el.value}}}for(const [id,key,def] of [['topKInput','top_k',40],['ctxInput','num_ctx',8192],['tokensInput','max_tokens',2048]]){const el=$('#'+id);if(el){el.value=c[key]||def;el.onchange=async()=>{const n=Number(el.value);if(!Number.isFinite(n)||n<Number(el.min)||n>Number(el.max)){toast(`Value must be between ${el.min} and ${el.max}`);el.value=c[key]||def;return}await api('/api/settings','PUT',{[key]:String(n)});state.settings[key]=String(n)}}}renderAgentSettings(c);renderMcpList();renderPromptList();renderSkillList();updateToolCount();updateAgentInstructionsPreview();updateChatAvailability()}
