function renderAgentSettings(c){const toggle=$('#agentArchitectureEnabled');if(toggle){toggle.checked=!['0','false','off','no'].includes(String(c.agent_architecture??'true').toLowerCase());toggle.onchange=async()=>{try{await api('/api/settings','PUT',{agent_architecture:toggle.checked});state.settings.agent_architecture=String(toggle.checked);toast(toggle.checked?'Planning and verification enabled':'Planning and verification disabled')}catch(e){toggle.checked=!toggle.checked;toast(e.message)}}}for(const item of AGENT_SETTING_FIELDS){const el=$('#'+item.id);if(!el)continue;const value=Number(c[item.key]??item.def);el.value=Number.isFinite(value)?value:item.def;el.onchange=async()=>{const n=Number(el.value);if(!Number.isInteger(n)||n<item.min||n>item.max){toast(`${el.previousElementSibling?.textContent||'Value'} must be between ${item.min} and ${item.max}`);el.value=String(c[item.key]??item.def);return}try{await api('/api/settings','PUT',{[item.key]:String(n)});state.settings[item.key]=String(n);toast('Agent setting saved')}catch(e){el.value=String(state.settings[item.key]??item.def);toast(e.message)}}}const reset=$('#resetAgentSettings');if(reset)reset.onclick=async()=>{const values={agent_architecture:'true'};for(const item of AGENT_SETTING_FIELDS)values[item.key]=String(item.def);try{await api('/api/settings','PUT',values);Object.assign(state.settings,values);renderAgentSettings(state.settings);toast('Agent settings reset to defaults')}catch(e){toast('Could not reset agent settings: '+e.message)}}}
function selected(type,id){return (selections[type]||[]).includes(id)}
async function setSelection(type,id,on){const list=new Set(selections[type]||[]);on?list.add(id):list.delete(id);selections[type]=[...list];if(currentSession)await api(`/api/sessions/${currentSession}/selections`,'PUT',selections);renderRight();updateToolCount();updateAgentInstructionsPreview()}
function selectionRow(item, type, sub = '', actions = '') {
    const row = document.createElement('div');
    row.className = 'tool-item selection-item';
    const enabled = type === 'mcp' ? true : !([0, '0', false, 'false', null, undefined].includes(item.enabled));
    let statusClass = enabled ? 'running' : 'stopped';
    let statusText = enabled ? 'Enabled' : 'Disabled';
    if (type === 'mcp') {
        statusClass = item.starting ? 'starting' : item.running ? 'running' : 'stopped';
        statusText = item.starting ? 'Starting' : item.running ? 'Running' : 'Stopped';
    }
    row.innerHTML = `
        <div class="item-main-row">
            <label class="item-select-label" title="${enabled ? 'Include in this conversation' : 'Disabled globally — enable before selecting for a chat'}">
                <input type="checkbox" class="item-select" ${selected(type,item.id)?'checked':''} ${enabled?'':'disabled'}>
            </label>
            <span class="status-dot ${statusClass}" title="${statusText}"></span>
            <span class="item-name">${esc(item.name)}</span>
        </div>
        <div class="item-controls-row">${actions}${type === 'mcp' ? '' : `
            <button class="tool-action enable-toggle" title="${enabled?'Disable globally — exclude from all chats':'Enable globally — allow selection in chats'}" aria-label="${enabled?'Disable globally':'Enable globally'}">${enabled?'◉':'○'}</button>`}
        </div>
        <div class="item-status-row"><span class="status-label">${statusText}</span><span class="item-status-detail">${esc(sub)}</span></div>`;
    row.querySelector('.item-select').onchange = e => setSelection(type,item.id,e.target.checked);
    const enableToggle = row.querySelector('.enable-toggle');
    if (enableToggle) enableToggle.onclick = async () => {
        const nextEnabled = !enabled;
        try {
            await api((type==='prompts'?'/api/prompts/':'/api/skills/')+item.id,'PATCH',{enabled:nextEnabled});
            if (!nextEnabled) {
                const key = type==='prompts' ? 'prompts' : type;
                selections[key] = (selections[key]||[]).filter(id=>id!==item.id);
                if (currentSession) await api(`/api/sessions/${currentSession}/selections`,'PUT',selections);
            }
            await refresh();
        } catch(err) { toast(err.message); }
    };
    return row;
}
function renderMcpList(){const root=$('#mcpList');if(!root)return;root.innerHTML='';const items=(state.skills||[]).filter(x=>x.kind==='mcp');items.forEach(s=>{const toolCount=(s.tools||[]).length;const status=s.running?`Running · ${toolCount} ${toolCount===1?'tool':'tools'}`:`Stopped · ${toolCount} ${toolCount===1?'tool':'tools'} discovered`;const action=`<button class="tool-action mcp-tools" title="View available tools" aria-label="View available tools"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 5.5h14M3 10h14M3 14.5h14"/><circle cx="6" cy="5.5" r="1.5"/><circle cx="13" cy="10" r="1.5"/><circle cx="8" cy="14.5" r="1.5"/></svg></button>${s.example_usage?'<button class="tool-action example-btn" title="Send MCP example to chat" aria-label="Send MCP example to chat">↑</button>':''}<button class="tool-action server-toggle" title="${s.running?'Disconnect / Stop':'Connect / Start'}">${s.running?'■':'▶'}</button><button class="tool-action mcp-logs" title="View server logs">≡</button><button class="tool-action edit-tool" title="Edit MCP configuration">✎</button>`;const row=selectionRow(s,'mcp',`${s.managed_locally===0?'Remote endpoint':'Local MCP'} · ${status}`,action);row.querySelector('.mcp-tools').onclick=()=>showMcpTools(s);row.querySelector('.edit-tool').onclick=()=>editMcp(s);const example=row.querySelector('.example-btn');if(example)example.onclick=()=>sendText(s.example_usage);row.querySelector('.mcp-logs').onclick=()=>{openModal(`${s.name} · Logs`,`<div class="mcp-logs-head"><span id="mcpLogStatus">${s.running?'CONNECTED':'DISCONNECTED'}</span><button type="button" class="secondary-btn" id="refreshMcpLogs">Refresh</button></div><pre class="mcp-log-output" id="mcpLogOutput">Loading logs…</pre>`,'Close',null,'MCP DIAGNOSTICS');loadMcpLogs(s.id);$('#refreshMcpLogs').onclick=()=>loadMcpLogs(s.id);mcpLogTimer=setInterval(()=>loadMcpLogs(s.id),2500)};row.querySelector('.server-toggle').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await api(`/api/skills/${s.id}/${s.running?'stop':'start'}`,'POST',{});await refresh();toast(s.running?'MCP server disconnected/stopped':'MCP server connected/started')}catch(err){toast(err.message);await refresh()}};root.append(row)});$('#mcpSummary').textContent=items.length?`${items.filter(x=>x.enabled).length} enabled · ${items.filter(x=>x.running).length} running`:'No MCP servers configured';$('#mcpCount').textContent=items.length;if(!items.length)root.innerHTML='<div class="empty-tools">Add a remote MCP endpoint or configure a locally managed server.</div>'}
function mcpToolCard(tool,index){const schema=tool.inputSchema||tool.input_schema||null;const properties=schema?.properties||{};const required=new Set(schema?.required||[]);const args=Object.entries(properties).map(([name,meta])=>`<div class="mcp-tool-arg"><div><b>${esc(name)}</b>${required.has(name)?'<span class="mcp-required">REQUIRED</span>':''}</div><small>${esc(meta?.type||'any')}${meta?.description?' · '+esc(meta.description):''}</small></div>`).join('');const schemaBlock=schema?`<details class="mcp-tool-schema"><summary>Input schema</summary><pre>${esc(JSON.stringify(schema,null,2))}</pre></details>`:'';return `<article class="mcp-tool-card"><div class="mcp-tool-card-head"><span class="mcp-tool-index">${String(index+1).padStart(2,'0')}</span><div><h3>${esc(tool.name||'Unnamed tool')}</h3><p>${esc(tool.description||'No description provided by this MCP server.')}</p></div></div>${args?`<div class="mcp-tool-args"><div class="mcp-tool-subtitle">INPUT PARAMETERS · ${Object.keys(properties).length}</div>${args}</div>`:'<div class="mcp-tool-noargs">No input parameters declared.</div>'}${schemaBlock}</article>`}
async function showMcpTools(server){const initial=Array.isArray(server.tools)?server.tools:[];openModal(`${server.name} · Available tools`,'<div class="mcp-tools-loading"><span class="spinner"></span><span>Loading tool catalog…</span></div>','Done',null,'MCP TOOL CATALOG');try{let tools=initial;if(server.running){const result=await api(`/api/skills/${server.id}/refresh`,'POST',{});tools=Array.isArray(result.tools)?result.tools:tools;server.tools=tools}const body=$('#modalBody');if(!body)return;if(!tools.length){body.innerHTML=`<div class="mcp-tools-empty"><div class="mcp-tools-empty-icon">⌘</div><h3>No tools currently available</h3><p>${server.running?'The server is connected but did not publish any tools.':'Connect or start this MCP server to discover its tools, then open this catalog again.'}</p></div>`;return}body.innerHTML=`<div class="mcp-tools-overview"><div><b>${tools.length}</b><span>${tools.length===1?'tool available':'tools available'}</span></div><small>${esc(server.name)} · ${server.running?'Connected':'Last discovered catalog'}</small></div><div class="mcp-tool-list">${tools.map((tool,index)=>mcpToolCard(tool,index)).join('')}</div>`}catch(error){const body=$('#modalBody');if(body)body.innerHTML=`<div class="mcp-tools-empty"><div class="mcp-tools-empty-icon">!</div><h3>Could not load tools</h3><p>${esc(error.message||'The MCP tool catalog could not be retrieved.')}</p></div>`}}
function renderPromptList(){const root=$('#promptList');if(!root)return;root.innerHTML='';const prompts=[...(state.prompts||[])].sort((a,b)=>(a.order_index??0)-(b.order_index??0));prompts.forEach((p,index)=>{const actions=`<button class="tool-action prompt-up" title="Move prompt up" aria-label="Move prompt up" ${index===0?'disabled':''}>↑</button><button class="tool-action prompt-down" title="Move prompt down" aria-label="Move prompt down" ${index===prompts.length-1?'disabled':''}>↓</button><button class="tool-action edit-tool" title="Edit prompt">✎</button><button class="tool-action delete-prompt" title="Delete prompt">×</button>`;const row=selectionRow(p,'prompts',`Order ${index+1}${p.description?' · '+p.description:''}`,actions);row.querySelector('.prompt-up').onclick=()=>movePrompt(index,-1);row.querySelector('.prompt-down').onclick=()=>movePrompt(index,1);row.querySelector('.edit-tool').onclick=()=>promptEditor(p);row.querySelector('.delete-prompt').onclick=()=>confirmAction(`Delete prompt “${p.name}”?`,async()=>{await api('/api/prompts/'+p.id,'DELETE');selections.prompts=selections.prompts.filter(x=>x!==p.id);if(currentSession)await api(`/api/sessions/${currentSession}/selections`,'PUT',selections);await refresh();updateAgentInstructionsPreview();updateToolCount()});root.append(row)});if(!prompts.length)root.innerHTML='<div class="empty-tools">Add reusable instructions and select them when needed.</div>'}
async function movePrompt(index,delta){const prompts=[...(state.prompts||[])].sort((a,b)=>(a.order_index??0)-(b.order_index??0));const target=index+delta;if(target<0||target>=prompts.length)return;[prompts[index],prompts[target]]=[prompts[target],prompts[index]];try{await api('/api/prompts/order','PUT',{ids:prompts.map(p=>p.id)});await refresh();updateAgentInstructionsPreview()}catch(e){toast(e.message)}}
function renderSkillList(){const root=$('#skillList');if(!root)return;root.innerHTML='';const items=(state.skills||[]).filter(x=>x.kind==='markdown');items.forEach(s=>{const action=s.example_usage?'<button class="tool-action skill-example-btn" title="Send skill example to chat" aria-label="Send skill example to chat">↑</button>':'';const row=selectionRow(s,'skills',s.path,action);row.querySelector('.item-name').onclick=()=>skillDetails(s);row.querySelector('.item-name').style.cursor='pointer';const example=row.querySelector('.skill-example-btn');if(example)example.onclick=()=>sendText(s.example_usage);root.append(row)});$('#skillSummary').textContent=items.length?`${items.length} local skill${items.length===1?'':'s'}`:'No skills imported';$('#skillCount').textContent=items.length;if(!items.length)root.innerHTML='<div class="empty-tools">Import a skill directory containing SKILL.md.</div>'}
function updateAgentInstructionsPreview(){
    const box=$('#agentInstructionsPreview');
    if(!box)return;
    const chosen=[...(state.prompts||[])].sort((a,b)=>(a.order_index??0)-(b.order_index??0)).filter(p=>![0,'0',false,'false'].includes(p.enabled)&&selected('prompts',p.id));
    const legacy=state.settings?.system_prompt||'';
    const defaultText="I am a helpful, precise, and reliable AI agent. I follow the user's instructions, use available skills and tools when useful, explain important actions, and clearly distinguish facts from assumptions.";
    const parts=[];
    if(legacy&&legacy!==defaultText)parts.push(legacy);
    parts.push(...chosen.map(p=>String(p.content||'').trim()).filter(Boolean));
    box.value=parts.length?parts.join('\n\n'):'No prompts selected. Select a prompt below to build the agent instructions.';
}
function updateToolCount(){const count=(items,ids)=>(items||[]).filter(x=>x.enabled!==false&&(ids||[]).includes(x.id)).length;const mcp=count((state.skills||[]).filter(x=>x.kind==='mcp'),selections.mcp);const skills=count((state.skills||[]).filter(x=>x.kind==='markdown'),selections.skills);const prompts=count(state.prompts||[],selections.prompts);const hint=$('#enabledCount');if(hint)hint.textContent=`${mcp} MCP · ${skills} skills · ${prompts} prompts selected`}
async function openSession(id){const sessionId=id;currentSession=sessionId;const s=state.sessions.find(x=>x.id===sessionId);if(s)currentProject=s.project_id;const saved=await api(`/api/sessions/${sessionId}/selections`).catch(()=>({prompts:[],skills:[],mcp:[]}));if(currentSession!==sessionId)return;selections=saved;if(!selections.initialized){selections={prompts:defaultPromptSelections(),skills:(state.skills||[]).filter(x=>x.enabled&&x.kind==='markdown').map(x=>x.id),mcp:[]};await api(`/api/sessions/${sessionId}/selections`,'PUT',selections);if(currentSession!==sessionId)return}await loadMessages(sessionId);if(currentSession===sessionId)renderAll()}
async function createSession(){try{const s=await api('/api/sessions','POST',{project_id:currentProject});currentSession=s.id;selections={prompts:defaultPromptSelections(),skills:(state.skills||[]).filter(x=>x.enabled&&x.kind==='markdown').map(x=>x.id),mcp:[]};await api(`/api/sessions/${s.id}/selections`,'PUT',selections);await refresh();await loadMessages();renderAll();$('#messageInput').focus()}catch(e){toast('Could not create conversation: '+e.message)}}
async function loadMessages(sessionId=currentSession){if(!sessionId)return;const msgs=await api('/api/sessions/'+sessionId+'/messages');if(currentSession!==sessionId)return;$('#welcome').style.display=msgs.length?'none':'block';$('#messages').innerHTML=msgs.map(messageHTML).join('');scrollBottom()}
function toolMarkup(t){return `<details class="tool-call"><summary>${esc(t.name)} · ${esc(t.status)}</summary><pre>INPUT\n${esc(JSON.stringify(t.arguments,null,2))}\n\nOUTPUT\n${esc(typeof t.result==='string'?t.result:JSON.stringify(t.result,null,2))}</pre></details>`}
function metricValue(value,digits=1){return Number.isFinite(value)?value.toLocaleString(undefined,{maximumFractionDigits:digits}):'—'}function traceEventHTML(e){if(e.type==='agent_recovery'){return `<details class="trace-event llm-event"><summary><span>Agent recovery · ${esc(e.phase||'execution')}</span><span class="trace-duration">Controller handoff</span></summary><div class="trace-content"><div class="trace-label">Recovery action</div><pre>${esc(e.action||'')}</pre><div class="trace-label">Reason</div><pre>${esc(e.reason||'')}</pre></div></details>`}if(e.type==='agent_fallback'){return `<details class="trace-event llm-event"><summary><span>Agent fallback · ${esc(e.phase||'control')}</span><span class="trace-duration">Controller recovery</span></summary><div class="trace-content"><div class="trace-label">Recovery strategy</div><pre>${esc(e.strategy||'')}</pre><div class="trace-label">Reason</div><pre>${esc(e.reason||'')}</pre><div class="trace-label">Fallback task contract</div><pre>${esc(JSON.stringify(e.plan||{},null,2))}</pre></div></details>`}if(e.type==='llm'){const u=e.usage||{},t=e.timing||{},ttft=t.ttft_ms==null?'—':`${metricValue(t.ttft_ms)} ms${t.ttft_estimated?'*':''}`,itl=t.itl_ms==null?'—':`${metricValue(t.itl_ms)} ms`,rate=t.tokens_per_second==null?'—':`${metricValue(t.tokens_per_second,2)} tok/s`;return `<details class="trace-event llm-event"><summary><span>${e.phase==='planning'?'PLAN':e.phase==='verification'?'VERIFY':'LLM'} #${e.index} · ${esc(e.provider||'model')} / ${esc(e.model||'')}</span><span class="trace-duration">${e.duration_ms??'—'} ms total</span></summary><div class="trace-content"><details class="trace-request"><summary>MCP servers & tools exposed · ${e.exposed_tool_names?.length||0} tools</summary><div class="trace-label">Selected MCP servers</div><pre>${esc(JSON.stringify(e.mcp_servers||[],null,2))}</pre><div class="trace-label">Exact exposed tool names</div><pre>${esc(JSON.stringify(e.exposed_tool_names||[],null,2))}</pre></details><details class="trace-request"><summary>Request sent to model · messages, tools & parameters</summary><div class="trace-label">Endpoint</div><pre>${esc(e.request?.endpoint||'Unavailable')}</pre><div class="trace-label">Exact request payload</div><pre>${esc(JSON.stringify(e.request?.payload??{},null,2))}</pre></details><div class="trace-metrics"><div class="trace-metric"><span>Input tokens</span><b>${u.input_tokens??'—'}</b></div><div class="trace-metric"><span>Output tokens</span><b>${u.output_tokens??'—'}</b></div><div class="trace-metric"><span>Total tokens</span><b>${u.total_tokens??'—'}</b></div><div class="trace-metric"><span>TTFT${t.ttft_estimated?' (est.)':''}</span><b>${ttft}</b></div><div class="trace-metric"><span>Inter-token latency</span><b>${itl}</b></div><div class="trace-metric"><span>Generation speed</span><b>${rate}</b></div></div><div class="trace-note">${t.ttft_estimated?'* TTFT is estimated from model load + prompt evaluation; Ollama non-streaming responses do not provide an exact first-token timestamp.':'Timing metrics are unavailable from this provider or response.'}${t.generation_duration_ms!=null?` Generation: ${metricValue(t.generation_duration_ms)} ms.`:''}</div>${e.validation_error?`<div class="trace-label">Validation error</div><pre>${esc(e.validation_error)}</pre>`:''}${e.verification_fallback?`<div class="trace-label">Verification recovery</div><pre>${esc(e.verification_fallback)}</pre>`:''}<div class="trace-label">Model response / tool decision</div><pre>${esc(e.response|| (e.tool_selection?'Requested tool execution':'No text returned'))}</pre>${e.model_response?.tool_calls?.length?`<div class="trace-label">Structured tool calls returned by model</div><pre>${esc(JSON.stringify(e.model_response.tool_calls,null,2))}</pre>`:''}</div></details>`}return `<details class="trace-event tool-event"><summary><span>Tool · ${esc(e.name)} · ${esc(e.status)}</span><span class="trace-duration">${e.duration_ms??'—'} ms</span></summary><div class="trace-content"><div class="trace-label">Arguments</div><pre>${esc(JSON.stringify(e.arguments,null,2))}</pre><div class="trace-label">Result</div><pre>${esc(typeof e.result==='string'?e.result:JSON.stringify(e.result,null,2))}</pre></div></details>`}function copyIconButton(kind,label){return `<button type="button" class="copy-message-btn" data-copy-target="${kind}" title="Copy ${label}" aria-label="Copy ${label}"><svg viewBox="0 0 20 20" aria-hidden="true"><rect x="7" y="6" width="10" height="11" rx="2"></rect><path d="M13 6V4.8A1.8 1.8 0 0 0 11.2 3H4.8A1.8 1.8 0 0 0 3 4.8v8.4A1.8 1.8 0 0 0 4.8 15H7"></path></svg></button>`}
async function copyMessageContent(button){const message=button.closest('.message');if(!message)return;const target=button.dataset.copyTarget==='trace'?message.querySelector('.execution-trace'):message.querySelector('.bubble');if(!target)return;const value=button.dataset.copyTarget==='trace'?(target.textContent||''):(target.innerText||target.textContent||'');try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(value);else{const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw Error('Clipboard copy was blocked')}toast(button.dataset.copyTarget==='trace'?'Trace copied':'Message copied')}catch(e){toast('Could not copy: '+e.message)}}
function messageHTML(m){let details={};try{details=JSON.parse(m.details||'{}')}catch{}const events=details.events||[],tools=Array.isArray(details)?details:(details.tools||[]),reasoning=Array.isArray(details)?'':(details.reasoning||'');const trace=events.length?`<details class="execution-trace"><summary><span>Execution trace · ${events.length} events</span>${copyIconButton('trace','trace')}</summary><div class="trace-list">${events.map(traceEventHTML).join('')}</div></details>`:tools.map(toolMarkup).join('');return `<div class="message ${m.role==='user'?'user':''}"><div class="message-avatar">${m.role==='user'?'YOU':'✦'}</div><div class="message-body"><div class="message-meta"><span>${m.role==='user'?'YOU':'AGENT'} · ${new Date(m.created*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</span>${copyIconButton('message',m.role==='user'?'request':'response')}</div><div class="bubble">${esc(m.content)}</div>${trace}${reasoning?`<details class="reasoning-output"><summary>Model reasoning</summary><pre>${esc(reasoning)}</pre></details>`:''}</div></div>`}
function appendMessage(role,content,tools=[],reasoning=''){const d=document.createElement('div');d.className='message '+(role==='user'?'user':'');d.innerHTML=`<div class="message-avatar">${role==='user'?'YOU':'✦'}</div><div class="message-body"><div class="message-meta"><span>${role==='user'?'YOU':'AGENT'} · NOW</span>${copyIconButton('message',role==='user'?'request':'response')}</div><div class="bubble">${esc(content)}</div>${reasoning?`<details class="reasoning-output"><summary>Model reasoning</summary><pre>${esc(reasoning)}</pre></details>`:''}${tools.map(toolMarkup).join('')}</div>`;$('#messages').append(d);scrollBottom()}
function scrollBottom(){$('#conversation').scrollTop=$('#conversation').scrollHeight}
async function sendText(text){if(!chatAvailable()){toast('Start Ollama before sending a message.');return}if(!text?.trim()||busy)return;$('#messageInput').value=text;await send()}
async function send(){const input=$('#messageInput');if(!input)return;const text=input.value.trim();if(!chatAvailable()){updateChatAvailability();toast('Chat is unavailable while Ollama is offline. Start Ollama from the Model panel.');return}if(!text||busy)return;try{if(!currentSession){const pendingSelections={prompts:[...(selections.prompts||[])],skills:[...(selections.skills||[])],mcp:[...(selections.mcp||[])]};const created=await api('/api/sessions','POST',{project_id:currentProject});currentSession=created.id;selections=pendingSelections;await api(`/api/sessions/${created.id}/selections`,'PUT',selections);state.sessions.unshift(created);renderProjects();$('#chatTitle').textContent=created.title;$('#projectLabel').textContent=(state.projects.find(x=>x.id===currentProject)?.name||'Unnamed project').toUpperCase()}const requestSessionId=currentSession;busy=true;const welcome=$('#welcome');if(welcome)welcome.style.display='none';appendMessage('user',text);input.value='';input.style.height='auto';const sendBtn=$('#sendBtn');if(sendBtn){sendBtn.disabled=true;sendBtn.innerHTML='<span>Working…</span><b>◌</b>'}const wait=document.createElement('div');wait.className='thinking';wait.innerHTML='<span class="spinner"></span> Agent is working — calling the model and tools…';$('#messages').append(wait);scrollBottom();try{const r=await api('/api/chat','POST',{session_id:requestSessionId,message:text,selections:{prompts:[...(selections.prompts||[])],skills:[...(selections.skills||[])],mcp:[...(selections.mcp||[])]}});addUsage(r.usage);if(currentSession===requestSessionId){wait.remove();appendMessage('assistant',r.content,r.tools||[],r.reasoning||'');await loadMessages(requestSessionId)}else{wait.remove()}}catch(e){if(currentSession===requestSessionId){wait.remove();appendMessage('assistant','Request failed: '+e.message)}toast(e.message)}finally{busy=false;if(sendBtn)sendBtn.innerHTML='<span>Send</span><b>↑</b>';await refresh();updateChatAvailability();if(currentSession===requestSessionId)await loadMessages(requestSessionId)}}catch(e){busy=false;updateChatAvailability();toast('Could not send message: '+e.message)}}
function openModal(title,body,saveText='Save',onSave=null,eyebrow='CONFIGURATION'){const titleEl=$('#modalTitle'),eyebrowEl=$('#modalEyebrow'),bodyEl=$('#modalBody'),actions=$('#modalActions'),backdrop=$('#modalBackdrop');if(!titleEl||!eyebrowEl||!bodyEl||!actions||!backdrop){toast('The dialog could not be opened because a required interface element is missing.');return}titleEl.textContent=title;eyebrowEl.textContent=eyebrow;bodyEl.innerHTML=body;actions.innerHTML='<button class="secondary-btn" id="cancelModal">Cancel</button>'+(saveText?`<button class="primary-btn" id="saveModal">${saveText}</button>`:'');backdrop.classList.add('show');const cancel=$('#cancelModal');if(cancel)cancel.onclick=closeModal;const save=$('#saveModal');if(save)save.onclick=async()=>{save.disabled=true;save.textContent='Saving…';try{if(onSave)await onSave();closeModal()}catch(e){toast(e.message)}finally{const currentSave=$('#saveModal');if(currentSave){currentSave.disabled=false;currentSave.textContent=saveText}}}}
function closeModal(){const backdrop=$('#modalBackdrop');if(backdrop)backdrop.classList.remove('show');if(mcpLogTimer){clearInterval(mcpLogTimer);mcpLogTimer=null}}
function confirmDialog(title,message,onConfirm,eyebrow='CONFIRMATION'){openModal(title,`<div class="confirm-dialog"><div class="confirm-icon">!</div><div class="confirm-message">${message}</div></div>`,'Confirm',onConfirm,eyebrow);const action=$('#saveModal');if(action){action.textContent='Delete';action.classList.add('danger-confirm')}}
async function loadMcpLogs(sid){const out=$('#mcpLogOutput');if(!out)return;try{const r=await api(`/api/skills/${sid}/logs`);const el=$('#mcpLogOutput');if(el){el.textContent=(r.logs||[]).join('\n')||'No log output yet.';el.scrollTop=el.scrollHeight;const status=$('#mcpLogStatus');if(status)status.textContent=r.running?'RUNNING':'STOPPED'}}catch(e){const el=$('#mcpLogOutput');if(el)el.textContent='Could not retrieve logs: '+e.message}}
function field(label,id,value='',type='text',hint=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}">${hint?`<small>${hint}</small>`:''}</div>`}
function textarea(label,id,value='',hint=''){return `<div class="field"><label for="${id}">${label}</label><textarea id="${id}">${esc(value)}</textarea>${hint?`<small>${hint}</small>`:''}</div>`}
function argsForForm(raw){let a=[];try{a=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{}return a.map(v=>{const x=String(v);return /[\s"]/.test(x)?'"'+x.replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"':x}).join(' ')}
function envForForm(raw){let e={};try{e=raw&&typeof raw==='object'?raw:JSON.parse(raw||'{}')}catch{}return Object.entries(e).map(([k,v])=>`${k}=${v}`).join('\n')}
async function renameProject(p){openModal('Rename project',field('Project name','renameValue',p.name),'Save',async()=>{await api('/api/projects/'+p.id,'PATCH',{name:$('#renameValue').value});await refresh()})}
async function deleteProject(p){confirmDialog('Delete project',`Delete <strong>${esc(p.name)}</strong> and all conversations inside it? This action cannot be undone.`,async()=>{await api('/api/projects/'+p.id,'DELETE');collapsedProjects.delete(p.id);if(currentProject===p.id){currentProject=state.projects.find(x=>x.id!==p.id)?.id||'default';currentSession=null}await refresh()},'DELETE PROJECT')}
async function renameSession(s){openModal('Rename conversation',field('Conversation name','renameValue',s.title),'Save',async()=>{await api('/api/sessions/'+s.id,'PATCH',{title:$('#renameValue').value});await refresh()})}
async function deleteSession(s){confirmDialog('Delete conversation',`Are you sure you want to delete <strong>${esc(s.title)}</strong>? This conversation and its messages will be permanently deleted.`,async()=>{await api('/api/sessions/'+s.id,'DELETE');if(currentSession===s.id)currentSession=null;await refresh()},'DELETE CONVERSATION')}
function skillDetails(s){const tools=(s.tools||[]).map(t=>`<details class="tool-call"><summary>${esc(t.name)}</summary><pre>${esc(t.description||'No description')}\n\nINPUT SCHEMA\n${esc(JSON.stringify(t.inputSchema||{},null,2))}</pre></details>`).join('');const logPanel=s.kind==='mcp'?`<div class="mcp-logs-head"><label>Server output / diagnostics</label><span id="mcpLogStatus">${s.running?'RUNNING':'STOPPED'}</span><button type="button" class="secondary-btn" id="refreshMcpLogs">Refresh</button></div><pre class="mcp-log-output" id="mcpLogOutput">Loading server logs…</pre>`:'';const body=`<div class="field"><label>Type</label><input disabled value="${s.kind==='mcp'?'MCP server':'Markdown skill'}"></div>${field('Name','skillName',s.name)}${field('Path / working directory','skillPath',s.path)}${s.kind==='mcp'?`${field('Launch command','skillCommand',s.command||'')}<div class="field"><label for="skillTransport">MCP transport</label><select id="skillTransport"><option value="auto" ${(!s.transport||s.transport==='auto')?'selected':''}>Auto detect</option><option value="stdio" ${s.transport==='stdio'?'selected':''}>STDIO</option><option value="http" ${s.transport==='http'?'selected':''}>Streamable HTTP</option></select><small>Choose HTTP when the MCP server exposes an HTTP endpoint. Auto detect remains available as a fallback.</small></div>${field('MCP HTTP endpoint URL','skillEndpoint',s.endpoint||'','url','Required for Streamable HTTP. Enter the URL printed by your MCP server, including its path.')} ${field('Additional command-line arguments (optional)','skillArgs',argsForForm(s.args),'text','Optional extra arguments, for example: --port 8080')}${textarea('Environment variables (optional)','skillEnv',envForForm(s.env),'One per line, for example: API_KEY=your-token')}${textarea('Example usage (optional) — the Try button sends this directly to chat','skillExample',s.example_usage||'')}<div class="field"><label>Server status</label><input disabled value="${s.running?'Running':'Stopped'} · ${(s.tools||[]).length} discovered tools"></div><div class="field"><label>Discovered tools (${(s.tools||[]).length})</label>${tools||'<small>No tools discovered yet. Start the server to discover its tools.</small>'}</div>${logPanel}`:`<div class="field"><label>Example usage (optional)</label><textarea id="skillExample" rows="3" placeholder="A sample request to send to chat">${esc(s.example_usage||'')}</textarea></div><small>Markdown skill content is loaded from this file and added to the agent instructions.</small>`}`;openModal('Manage skill / MCP',body,'Save changes',async()=>{const args=$('#skillArgs')?.value||'';const env=$('#skillEnv')?.value||'';const payload={name:$('#skillName').value,path:$('#skillPath').value,...(s.kind==='mcp'?{command:$('#skillCommand').value,transport:$('#skillTransport').value,endpoint:$('#skillEndpoint').value,args,env,example_usage:$('#skillExample').value}:{example_usage:$('#skillExample')?.value||''})};closeModal();toast('Configuration saved — applying changes in the background…');const r=await api('/api/skills/'+s.id,'PATCH',payload);await refresh();if(r.error)toast('Configuration saved, but MCP restart failed: '+r.error);else if(r.starting)toast('MCP configuration changed. Server is restarting.')});if(s.kind==='mcp'){const ts=$('#skillTransport');if(ts)ts.onchange=()=>{const ep=$('#skillEndpoint')?.closest('.field');if(ep)ep.style.display=ts.value==='http'?'':'none'};const ep=$('#skillEndpoint')?.closest('.field');if(ep)ep.style.display=(s.transport==='http')?'':'none';loadMcpLogs(s.id);const refreshBtn=$('#refreshMcpLogs');if(refreshBtn)refreshBtn.onclick=()=>loadMcpLogs(s.id);mcpLogTimer=setInterval(()=>loadMcpLogs(s.id),2500)}const actions=$('#modalActions');const addAction=(label,fn)=>{const b=document.createElement('button');b.className='secondary-btn';b.textContent=label;b.onclick=async()=>{b.disabled=true;try{await fn()}catch(e){toast(e.message)}finally{b.disabled=false}};actions.prepend(b)};if(s.kind==='mcp')addAction(s.running?'Stop server':'Start & discover tools',async()=>{const r=await api(`/api/skills/${s.id}/${s.running?'stop':'start'}`,'POST',{});await refresh();skillDetails(state.skills.find(x=>x.id===s.id));toast(s.running?'MCP server stopped':`${(r.tools||[]).length} tools discovered`)});addAction(s.enabled?'Disable':'Enable',async()=>{await api('/api/skills/'+s.id,'PATCH',{enabled:!s.enabled});await refresh();closeModal()});addAction('Delete',async()=>{if(confirm('Delete this skill or MCP configuration?')){await api('/api/skills/'+s.id,'DELETE');await refresh();closeModal()}})}
function addSkill(){openModal('Import local skill',`${field('Skill name','skillName','New skill')}${field('Skill directory or SKILL.md path','skillPath','','text','Choose a local directory containing SKILL.md, or a Markdown file.')}`,'Import skill',async()=>{const path=$('#skillPath').value.trim();await api('/api/skills','POST',{kind:'markdown',name:$('#skillName').value,path});closeModal();await refresh();toast('Local skill imported')},'SKILL MANAGEMENT')}
function addMcp(){openModal('Add MCP server',`<div class="field"><label for="mcpName">Server name</label><input id="mcpName" value="New MCP server"></div><label class="check-field"><input type="checkbox" id="mcpManaged" checked> Manage this MCP server locally</label><div id="mcpLocalFields">${field('Local project directory','mcpPath','','text','Working directory used when starting the local server.')}${field('Start command','mcpCommand','python server.py')}${field('Local HTTP endpoint URL (optional)','mcpLocalEndpoint','','url','Used only for a local Streamable HTTP server; auto-detection is available in Auto detect mode.')}${field('Additional arguments','mcpArgs','','text','Optional command-line arguments.')}${textarea('Environment variables','mcpEnv','','Optional KEY=value entries, one per line.')}</div><div id="mcpRemoteFields" hidden>${field('MCP endpoint URL','mcpEndpoint','','url','Remote Streamable HTTP endpoint, e.g. https://host.example/mcp')}${textarea('HTTP headers (JSON)','mcpHeaders','{}','Optional authentication headers, e.g. {"Authorization":"Bearer …"}.')}</div>${textarea('Example usage / prompt (optional)','mcpExample','','A short request to send to the agent when you click the example button.')}<div class="field"><label for="mcpTransport">Transport</label><select id="mcpTransport"><option value="auto" selected>Auto detect (local)</option><option value="stdio">STDIO (local)</option><option value="http">Streamable HTTP (local)</option></select></div>`,'Add server',async()=>{const managed=$('#mcpManaged').checked,headersText=$('#mcpHeaders')?.value||'{}';let headers={};try{headers=JSON.parse(headersText)}catch{throw Error('HTTP headers must be valid JSON')}const payload={kind:'mcp',name:$('#mcpName').value,managed_locally:managed,path:$('#mcpPath')?.value||'',command:$('#mcpCommand')?.value||'',args:$('#mcpArgs')?.value||'',env:$('#mcpEnv')?.value||'',endpoint:managed?($('#mcpLocalEndpoint')?.value||''):($('#mcpEndpoint')?.value||''),auth_headers:headers,example_usage:$('#mcpExample')?.value||'',transport:managed?$('#mcpTransport').value:'http'};await api('/api/skills','POST',payload);closeModal();await refresh();toast('MCP server configuration saved')},'MCP CONFIGURATION');const toggle=$('#mcpManaged');toggle.onchange=()=>{$('#mcpLocalFields').hidden=!toggle.checked;$('#mcpRemoteFields').hidden=toggle.checked;const tr=$('#mcpTransport');tr.disabled=!toggle.checked;if(!toggle.checked)tr.value='http'};toggle.onchange()}
function editMcp(s){openModal('MCP server settings',`${field('Server name','editMcpName',s.name)}<label class="check-field"><input type="checkbox" id="editMcpManaged" ${s.managed_locally?'checked':''}> Manage this MCP server locally</label><div id="editMcpLocal">${field('Local project directory','editMcpPath',s.path||'')}${field('Start command','editMcpCommand',s.command||'')}${field('Local HTTP endpoint URL (optional)','editMcpLocalEndpoint',s.endpoint||'','url')}${field('Arguments','editMcpArgs',Array.isArray(JSON.parse(s.args||'[]'))?JSON.parse(s.args||'[]').join(' '):'')}${textarea('Environment variables','editMcpEnv',Object.entries(JSON.parse(s.env||'{}')).map(([k,v])=>`${k}=${v}`).join('\n'))}</div><div id="editMcpRemote">${field('Remote MCP endpoint URL','editMcpEndpoint',s.endpoint||'','url')}${textarea('HTTP headers (JSON)','editMcpHeaders',s.auth_headers||'{}')}</div>${textarea('Example usage / prompt (optional)','editMcpExample',s.example_usage||'A short request demonstrating how to use this MCP server.')}<div class="field"><label>Transport</label><select id="editMcpTransport"><option value="http" ${s.transport==='http'?'selected':''}>Streamable HTTP</option><option value="stdio" ${s.transport==='stdio'?'selected':''}>STDIO</option><option value="auto" ${s.transport==='auto'?'selected':''}>Auto detect</option></select></div>`,'Save changes',async()=>{let headers={};try{headers=JSON.parse($('#editMcpHeaders').value||'{}')}catch{throw Error('HTTP headers must be valid JSON')}await api('/api/skills/'+s.id,'PATCH',{name:$('#editMcpName').value,managed_locally:$('#editMcpManaged').checked,path:$('#editMcpPath')?.value||'',command:$('#editMcpCommand')?.value||'',args:$('#editMcpArgs')?.value||'',env:$('#editMcpEnv')?.value||'',endpoint:$('#editMcpManaged').checked?($('#editMcpLocalEndpoint')?.value||''):($('#editMcpEndpoint')?.value||''),auth_headers:headers,example_usage:$('#editMcpExample').value||'',transport:$('#editMcpTransport').value});closeModal();await refresh();toast('MCP settings updated')},'MCP CONFIGURATION');const toggle=$('#editMcpManaged');const sync=()=>{$('#editMcpLocal').hidden=!toggle.checked;$('#editMcpRemote').hidden=toggle.checked};toggle.onchange=sync;sync()}
function manageSkillsModal(){const items=state.skills.map(s=>`<div class="manage-skill"><span class="tool-indicator ${s.running?'on':''}"></span><div class="manage-skill-info"><b>${esc(s.name)}</b><small>${s.kind==='mcp'?'MCP server':'Markdown skill'} · ${s.enabled?'Enabled':'Disabled'}${s.kind==='mcp'?' · '+(s.running?'Running':'Stopped'):''}</small></div><button class="secondary-btn" data-edit="${s.id}">Manage</button></div>`).join('');openModal('Skills & MCP servers',`${items||'<p class="empty-tools">No skills or MCP servers have been added yet.</p>'}<p class="form-note">Manage, enable, disable, start, stop, inspect discovered tools, edit example usage, or remove existing integrations.</p>`,'＋ Add skill / MCP',async()=>{closeModal();addSkill()},'SKILL REGISTRY');$$('[data-edit]').forEach(b=>b.onclick=()=>{const s=state.skills.find(x=>x.id===b.dataset.edit);if(s)skillDetails(s)})}
function promptEditor(p=null){const isEdit=!!p;openModal(isEdit?'Edit prompt':'Add prompt',`${field('Prompt name','promptName',p?.name||'')}${field('Description (optional)','promptDescription',p?.description||'')}${textarea('Prompt content','promptContent',p?.content||'')}`,'Save prompt',async()=>{const payload={name:$('#promptName').value,description:$('#promptDescription').value,content:$('#promptContent').value};const result=await api(isEdit?'/api/prompts/'+p.id:'/api/prompts',isEdit?'PATCH':'POST',payload);await refresh();updateAgentInstructionsPreview();updateToolCount();toast(isEdit?'Prompt updated':'Prompt added; select it explicitly to include it in a conversation')})}
function confirmAction(message,action){openModal('Confirm action',`<p>${esc(message)}</p>`,'Delete',action,'CONFIRMATION')}
async function settingsModal(){await refreshModelStatus();const c=state.settings;openModal('Application settings',`<div class="settings-block"><h3>Model connection</h3><div class="field"><label>Model provider</label><select id="provider"><option value="ollama" ${c.provider==='ollama'?'selected':''}>Local Ollama</option><option value="openai" ${c.provider==='openai'?'selected':''}>External · OpenAI-compatible API</option></select></div><div class="field"><label for="model">Ollama model</label><select id="model">${modelOptions(c.model||'llama3.2')}</select><small>Models are loaded from the connected Ollama server. Start Ollama to refresh its model list.</small></div>${field('API base URL','baseUrl',c.base_url)}${field('API key / token (optional for local providers)','apiKey',c.api_key,'password','Stored locally in the application settings database.')}</div><div class="settings-block"><h3>Appearance</h3><div class="field"><label>Theme</label><select id="theme"><option value="dark" ${c.theme==='dark'?'selected':''}>Dark</option><option value="light" ${c.theme==='light'?'selected':''}>Light</option></select></div></div><div class="settings-block"><h3>MCP servers</h3><p>Enable servers globally to make their tools available to chats. Select a server in the right panel to use it in the current conversation.</p><button type="button" class="secondary-btn wide-btn" id="manageMcpBtn">Manage MCP servers (${state.skills.filter(x=>x.kind==='mcp').length})</button><button type="button" class="primary-btn wide-btn" id="quickAddMcpBtn">＋ Add MCP server</button></div><div class="settings-block"><h3>Skills</h3><p>Import local Markdown skills. Disabled skills are excluded from all chats.</p><button type="button" class="secondary-btn wide-btn" id="manageSkillsBtn">Manage skills (${state.skills.filter(x=>x.kind==='markdown').length})</button><button type="button" class="primary-btn wide-btn" id="quickAddSkillBtn">＋ Add skill</button></div><div class="settings-block"><h3>Prompts</h3><p>Create reusable instructions and select them per conversation. Disabled prompts are excluded from all chats.</p><button type="button" class="secondary-btn wide-btn" id="managePromptsBtn">Manage prompts (${state.prompts.length})</button><button type="button" class="primary-btn wide-btn" id="quickAddPromptBtn">＋ Add prompt</button></div><p class="form-note">External providers use an OpenAI-compatible /chat/completions endpoint. Ollama uses its native /api/chat endpoint.</p>`,'Save settings',async()=>{const next={provider:$('#provider').value,model:$('#model').value,base_url:$('#baseUrl').value,api_key:$('#apiKey').value,theme:$('#theme').value};const prev=state.settings||{};if(next.provider!==prev.provider||next.model!==prev.model||next.base_url!==prev.base_url)resetUsageSession();await api('/api/settings','PUT',next);applyTheme($('#theme').value);await refresh()});const modelSelect=$('#model');if(modelSelect){modelSelect.onchange=()=>{const v=modelSelect.value;if(v){const right=$('#activeModelSelect');if(right)right.value=v;}};}const manageBtn=$('#manageSkillsBtn'),quickAddBtn=$('#quickAddSkillBtn'),manageMcp=$('#manageMcpBtn'),quickAddMcp=$('#quickAddMcpBtn'),managePrompts=$('#managePromptsBtn'),quickAddPrompt=$('#quickAddPromptBtn');if(manageBtn)manageBtn.onclick=()=>{closeModal();renderSkillList()};if(quickAddBtn)quickAddBtn.onclick=()=>{closeModal();addSkill()};if(manageMcp)manageMcp.onclick=()=>{closeModal();renderMcpList()};if(quickAddMcp)quickAddMcp.onclick=()=>{closeModal();addMcp()};if(managePrompts)managePrompts.onclick=()=>{closeModal();renderPromptList()};if(quickAddPrompt)quickAddPrompt.onclick=()=>{closeModal();promptEditor()}}
function paramsModal(){const c=state.settings;openModal('Model parameters',`${field('Temperature','temperature',c.temperature)}${field('Top P','topP',c.top_p)}${field('Top K','topK',c.top_k)}${field('Context window (tokens)','numCtx',c.num_ctx)}${field('Repeat penalty','repeatPenalty',c.repeat_penalty)}${field('Maximum output tokens','maxTokens',c.max_tokens)}`,'Save parameters',async()=>{await api('/api/settings','PUT',{temperature:$('#temperature').value,top_p:$('#topP').value,top_k:$('#topK').value,num_ctx:$('#numCtx').value,repeat_penalty:$('#repeatPenalty').value,max_tokens:$('#maxTokens').value});await refresh()})}
function applyTheme(theme){document.body.classList.toggle('light',theme==='light');document.documentElement.dataset.theme=theme==='light'?'light':'dark'}
$('#newProjectBtn').onclick=()=>openModal('Create project',field('Project name','projectName','New project'),'Create project',async()=>{const p=await api('/api/projects','POST',{name:$('#projectName').value});currentProject=p.id;currentSession=null;await refresh()});$('#messages').addEventListener('click',e=>{const button=e.target.closest('.copy-message-btn');if(!button)return;e.preventDefault();e.stopPropagation();copyMessageContent(button)});$('#sendBtn').onclick=send;$('#messageInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}});$('#messageInput').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,220)+'px'});$$('.starter').forEach(b=>b.onclick=()=>{$('#messageInput').value=b.dataset.prompt;$('#messageInput').focus()});$('#renameChatBtn').onclick=()=>{const s=state.sessions.find(x=>x.id===currentSession);if(s)renameSession(s)};$('#deleteChatBtn').onclick=()=>{const s=state.sessions.find(x=>x.id===currentSession);if(s)deleteSession(s)};$('#addSkillBtn').onclick=addSkill;$('#addMcpBtn').onclick=addMcp;$('#addPromptBtn').onclick=()=>promptEditor();$('#settingsBtn').onclick=settingsModal;$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};$('#aboutBtn').onclick=()=>openModal('About Agent Prototyping App',`<div style="text-align:center;padding:12px"><div class="welcome-orb">✦</div><h3>Agent Prototyping App</h3><p>Version 1.5.9</p><p>A local-first workspace for prototyping AI agents with Markdown skills, MCP servers, and configurable language models.</p><p>Powered by Python · FastAPI · HTML · CSS · JavaScript</p></div>`,'',null,'ABOUT');$('#startModelBtn').onclick=async()=>{const btn=$('#startModelBtn');if(!btn)return;const wasRunning=!!state.model_running;resetUsageSession();btn.disabled=true;btn.textContent=wasRunning?'Stopping…':'Starting…';try{const r=await api(`/api/model/${wasRunning?'stop':'start'}`,'POST',{});if(r.stopped===false&&r.message)toast(r.message);else toast(wasRunning?(r.already_stopped?'Ollama was already stopped':'Ollama stopped'):(r.already_running?'Ollama is already running':'Ollama start requested'));for(let i=0;i<40;i++){await new Promise(resolve=>setTimeout(resolve,500));await refreshModelStatus();if(wasRunning?!state.model_running:state.model_running)break}}catch(e){toast(e.message);await refreshModelStatus()}finally{renderRight()}};$('#exitBtn').onclick=async()=>{if(confirm('Close Agent Prototyping App and stop its server process?')){try{await api('/api/shutdown','POST',{});}catch(e){/* The server may stop before the response reaches the browser. */}try{window.open('','_self');window.close()}catch(e){}setTimeout(()=>{if(!window.closed)window.location.replace('about:blank')},250)}};
(async()=>{try{renderUsagePanel();await refresh();applyTheme(state.settings?.theme||'dark');if(state.sessions.length){const s=state.sessions[0];currentSession=s.id;currentProject=s.project_id;selections=await api(`/api/sessions/${s.id}/selections`).catch(()=>({prompts:[],skills:[],mcp:[]}));if(!selections.initialized){selections={prompts:defaultPromptSelections(),skills:(state.skills||[]).filter(x=>x.enabled&&x.kind==='markdown').map(x=>x.id),mcp:[]};await api(`/api/sessions/${s.id}/selections`,'PUT',selections)}await loadMessages();renderAll()}else{currentProject=state.projects[0]?.id||'default';selections={prompts:defaultPromptSelections(),skills:(state.skills||[]).filter(x=>x.enabled&&x.kind==='markdown').map(x=>x.id),mcp:[]};renderAll()}}catch(e){toast('Could not initialize app: '+e.message)}})();

// Keep Ollama state synchronized even when the user does not interact with the UI.
setInterval(refreshModelStatus,3000);